t.script:
document.addEventListener('DOMContentLoaded', function() {

  async function handleClick(e) {
    e.preventDefault();
    const btn = e.currentTarget;
    const url = btn.getAttribute('href');
    const card = btn.closest('.card, tr');

    btn.disabled = true;
    const originalHTML = btn.innerHTML;
    btn.innerHTML = '<span aria-hidden="true">...</span>';

    try {
      const response = await fetch(url, { method: 'GET' });
      const result = await response.json();

      if (!result.success) {
        alert(result.message || 'Error processing request');
        btn.disabled = false;
        btn.innerHTML = originalHTML;
        return;
      }

      // UI Update logic
      if (btn.classList.contains('btn-checkin')) {
        // Mark as checked in: update badge and toggle buttons
        updateStatus(card, 'Checked In', 'bg-success');

        // hide/disable checkin button, show/enable checkout button
        const actionCell = card.querySelector('td:last-child') || card.querySelector('.d-flex');
        if (actionCell) {
          const checkinBtn = actionCell.querySelector('a.btn-checkin');
          const checkoutBtn = actionCell.querySelector('a.btn-checkout');
          if (checkinBtn) {
            checkinBtn.classList.add('d-none');
          }
          if (checkoutBtn) {
            checkoutBtn.classList.remove('d-none');
            checkoutBtn.disabled = false;
          }
        }

      } else if (btn.classList.contains('btn-checkout')) {
        // After checkout, remove/hide both buttons and show "No Action"
        const actionCell = card.querySelector('td:last-child');
        if (actionCell) {
          actionCell.innerHTML = '';
          const noAction = document.createElement('span');
          noAction.className = 'text-muted small';
          noAction.textContent = 'No Action';
          actionCell.appendChild(noAction);
        } else {
          // mobile: hide buttons container
          const actions = card.querySelectorAll('a.btn-checkin, a.btn-checkout');
          actions.forEach(a => a.remove());
          const wrapper = card.querySelector('.card-body');
          if (wrapper) {
            const noAction = document.createElement('div');
            noAction.className = 'text-muted small mt-2';
            noAction.textContent = 'No Action';
            wrapper.appendChild(noAction);
          }
        }

        updateStatus(card, 'Checked Out', 'bg-danger');
      }

    } catch (err) {
      alert('Error: ' + err.message);
      btn.disabled = false;
      btn.innerHTML = originalHTML;
    }
  }

  // 🧩 Update the status cell or paragraph
  function updateStatus(card, newText, newClass) {
    // 🖥️ Desktop table (td:nth-child(6) = Status column)
    const statusCell = card.querySelector('td:nth-child(6)');
    if (statusCell) {
      statusCell.innerHTML = '<span class="badge ' + newClass + '">' + newText + '</span>';
      return;
    }

    // 📱 Mobile card (Status paragraph)
    const pTags = card.querySelectorAll('p');
    pTags.forEach(p => {
      if (p.textContent.includes('Status')) {
        // replace existing badge or append
        let span = p.querySelector('span.badge');
        if (!span) {
          span = document.createElement('span');
          p.appendChild(span);
        }
        span.textContent = newText;
        span.className = 'badge ' + newClass;
      }
    });
  }

  // Attach events to all checkin/checkout buttons
  document.querySelectorAll('a.btn-checkin, a.btn-checkout').forEach(btn => {
    btn.addEventListener('click', handleClick);
  });
});
